// DecodeNode decodes the typed JSON emitted by EncodeNode.
func DecodeNode(data []byte) (syntax.Node, error) {
	typeName, err := decodeType(data)
	if err != nil {
		return nil, err
	}
	switch typeName {
	case "File":
		return decodeFile(data)
	case "Comment":
		return decodeComment(data)
	case "Stmt":
		return decodeStmt(data)
	case "Assign":
		return decodeAssign(data)
	case "Redirect":
		return decodeRedirect(data)
	case "CallExpr":
		return decodeCallExpr(data)
	case "Subshell":
		return decodeSubshell(data)
	case "Block":
		return decodeBlock(data)
	case "IfClause":
		return decodeIfClause(data)
	case "WhileClause":
		return decodeWhileClause(data)
	case "ForClause":
		return decodeForClause(data)
	case "WordIter":
		return decodeWordIter(data)
	case "CStyleLoop":
		return decodeCStyleLoop(data)
	case "BinaryCmd":
		return decodeBinaryCmd(data)
	case "FuncDecl":
		return decodeFuncDecl(data)
	case "Word":
		return decodeWord(data)
	case "Lit":
		return decodeLit(data)
	case "SglQuoted":
		return decodeSglQuoted(data)
	case "DblQuoted":
		return decodeDblQuoted(data)
	case "CmdSubst":
		return decodeCmdSubst(data)
	case "ParamExp":
		return decodeParamExp(data)
	case "ArithmExp":
		return decodeArithmExp(data)
	case "ArithmCmd":
		return decodeArithmCmd(data)
	case "BinaryArithm":
		return decodeBinaryArithm(data)
	case "UnaryArithm":
		return decodeUnaryArithm(data)
	case "ParenArithm":
		return decodeParenArithm(data)
	case "FlagsArithm":
		return decodeFlagsArithm(data)
	case "CaseClause":
		return decodeCaseClause(data)
	case "CaseItem":
		return decodeCaseItem(data)
	case "TestClause":
		return decodeTestClause(data)
	case "BinaryTest":
		return decodeBinaryTest(data)
	case "UnaryTest":
		return decodeUnaryTest(data)
	case "ParenTest":
		return decodeParenTest(data)
	case "DeclClause":
		return decodeDeclClause(data)
	case "ArrayExpr":
		return decodeArrayExpr(data)
	case "ArrayElem":
		return decodeArrayElem(data)
	case "ExtGlob":
		return decodeExtGlob(data)
	case "ProcSubst":
		return decodeProcSubst(data)
	case "TimeClause":
		return decodeTimeClause(data)
	case "CoprocClause":
		return decodeCoprocClause(data)
	case "LetClause":
		return decodeLetClause(data)
	case "BraceExp":
		return decodeBraceExp(data)
	case "TestDecl":
		return decodeTestDecl(data)
	default:
		return nil, fmt.Errorf("unsupported syntax.Node type %q", typeName)
	}
}

// DecodeFile decodes a shell syntax tree into a File.
func DecodeFile(data []byte) (*syntax.File, error) {
	node, err := DecodeNode(data)
	if err != nil {
		return nil, err
	}
	file, ok := node.(*syntax.File)
	if !ok {
		return nil, fmt.Errorf("expected File, got %T", node)
	}
	return file, nil
}
